import { NextRequest, NextResponse } from 'next/server';
import { requireAuth } from '@/lib/auth';
import { scrapeWebsite } from '@/lib/firecrawl';
import { crawlPreviewSchema } from '@/lib/validations';
import { checkRateLimit } from '@/lib/rate-limit';
import { cacheGet, cacheSet } from '@/lib/redis';
import { sanitizeUrl } from '@/lib/sanitize';
import crypto from 'crypto';

export async function POST(req: NextRequest) {
  try {
    const userId = await requireAuth();
    const body = await req.json();
    const parsed = crawlPreviewSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        { error: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const rate = await checkRateLimit(`crawl:${userId}`);
    if (!rate.allowed) {
      return NextResponse.json(
        { error: 'Rate limit exceeded. Try again later.' },
        { status: 429, headers: { 'Retry-After': String(Math.ceil(rate.resetMs / 1000)) } }
      );
    }

    const url = sanitizeUrl(parsed.data.websiteUrl);
    const cacheKey = `crawl:${crypto.createHash('sha256').update(url).digest('hex')}`;

    const cached = await cacheGet<{ markdown: string; title?: string; description?: string }>(cacheKey);
    if (cached) {
      return NextResponse.json({ ...cached, sourceUrl: url, cached: true });
    }

    const scraped = await scrapeWebsite(url);
    await cacheSet(cacheKey, scraped, 1800);

    return NextResponse.json({
      markdown: scraped.markdown.slice(0, 2000),
      fullLength: scraped.markdown.length,
      title: scraped.title,
      description: scraped.description,
      sourceUrl: scraped.sourceUrl,
      cached: false,
    });
  } catch (err) {
    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    const message = err instanceof Error ? err.message : 'Crawl failed';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { requireAuth, getAuthUser } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { scrapeWebsite } from '@/lib/firecrawl';
import { triggerN8nWorkflow } from '@/lib/n8n';
import { generateRequestSchema } from '@/lib/validations';
import { optimizePromptForPlatform, type PlatformId } from '@/lib/platforms';
import { checkRateLimit } from '@/lib/rate-limit';
import { sanitizeUrl } from '@/lib/sanitize';
import { GeneratedPost } from '@/models/GeneratedPost';
import { PromptHistory } from '@/models/PromptHistory';
import { WorkflowExecution } from '@/models/WorkflowExecution';
import {
  ensureUser,
  deductCredit,
  trackUsage,
} from '@/lib/user-service';
import { enqueueGeneration } from '@/lib/queue';

export const maxDuration = 120;

export async function POST(req: NextRequest) {
  const start = Date.now();
  let executionId = uuidv4();

  try {
    const userId = await requireAuth();
    const authUser = await getAuthUser();
    const body = await req.json();
    const parsed = generateRequestSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: parsed.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const rate = await checkRateLimit(`generate:${userId}`);
    if (!rate.allowed) {
      return NextResponse.json(
        { error: 'Rate limit exceeded. Upgrade or wait before generating more content.' },
        { status: 429 }
      );
    }

    await connectDB();
    await ensureUser({
      clerkId: userId,
      email: authUser?.email ?? '',
      name: authUser?.name ?? 'User',
      imageUrl: authUser?.imageUrl,
    });

    const hasCredit = await deductCredit(userId, 1);
    if (!hasCredit) {
      return NextResponse.json(
        { error: 'Insufficient credits. Please upgrade your plan.' },
        { status: 402 }
      );
    }

    const { websiteUrl, userPrompt, platform } = parsed.data;
    const safeUrl = sanitizeUrl(websiteUrl);
    const optimizedPrompt = optimizePromptForPlatform(
      userPrompt,
      platform as PlatformId
    );
    executionId = uuidv4();

    await WorkflowExecution.create({
      userId,
      executionId,
      status: 'running',
      input: { websiteUrl: safeUrl, userPrompt, platform },
    });

    await GeneratedPost.create({
      userId,
      executionId,
      websiteUrl: safeUrl,
      userPrompt,
      platform,
      status: 'pending',
      content: '',
    });

    await PromptHistory.create({
      userId,
      websiteUrl: safeUrl,
      userPrompt,
      platform,
      optimizedPrompt,
    });

    const useQueue = process.env.USE_QUEUE === 'true';
    if (useQueue) {
      const scraped = await scrapeWebsite(safeUrl);
      const queued = await enqueueGeneration({
        userId,
        executionId,
        websiteUrl: safeUrl,
        scrapedContent: scraped.markdown,
        userPrompt,
        optimizedPrompt,
        platform,
      });

      if (queued.queued) {
        return NextResponse.json({
          status: 'queued',
          executionId,
          jobId: queued.jobId,
          message: 'Generation queued. Poll /api/history for results.',
        });
      }
    }

    const scraped = await scrapeWebsite(safeUrl);
    const result = await triggerN8nWorkflow({
      websiteUrl: safeUrl,
      scrapedContent: scraped.markdown,
      userPrompt,
      optimizedPrompt,
      platform: platform as PlatformId,
      userId,
      executionId,
    });

    const durationMs = Date.now() - start;

    await GeneratedPost.findOneAndUpdate(
      { executionId },
      {
        status: 'completed',
        content: result.content ?? '',
        summary: result.summary,
        qualityScore: result.qualityScore,
        wordCount: result.wordCount,
      }
    );

    await WorkflowExecution.findOneAndUpdate(
      { executionId },
      {
        status: 'completed',
        output: result,
        durationMs,
      }
    );

    await trackUsage(userId, platform, 1);

    return NextResponse.json({
      status: 'completed',
      executionId,
      platform: result.platform,
      platformName: result.platformName,
      websiteUrl: result.websiteUrl ?? safeUrl,
      summary: result.summary,
      content: result.content,
      qualityScore: result.qualityScore,
      wordCount: result.wordCount,
      generatedAt: result.generatedAt,
      preview: {
        title: scraped.title,
        description: scraped.description,
      },
      durationMs,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Generation failed';

    if (executionId) {
      await connectDB().catch(() => {});
      await GeneratedPost.findOneAndUpdate(
        { executionId },
        { status: 'failed', error: message }
      ).catch(() => {});
      await WorkflowExecution.findOneAndUpdate(
        { executionId },
        { status: 'failed', error: message }
      ).catch(() => {});
    }

    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    return NextResponse.json({ error: message, executionId }, { status: 500 });
  }
}

