import { NextRequest, NextResponse } from 'next/server';
import { requireAuth } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { GeneratedPost } from '@/models/GeneratedPost';
import { PromptHistory } from '@/models/PromptHistory';

export async function GET(req: NextRequest) {
  try {
    const userId = await requireAuth();
    await connectDB();

    const { searchParams } = new URL(req.url);
    const type = searchParams.get('type') ?? 'posts';
    const limit = Math.min(Number(searchParams.get('limit') ?? 20), 50);
    const page = Math.max(Number(searchParams.get('page') ?? 1), 1);
    const skip = (page - 1) * limit;

    if (type === 'prompts') {
      const prompts = await PromptHistory.find({ userId })
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limit)
        .lean();

      const total = await PromptHistory.countDocuments({ userId });
      return NextResponse.json({ prompts, total, page, limit });
    }

    const posts = await GeneratedPost.find({ userId })
      .sort({ createdAt: -1 })
      .skip(skip)
      .limit(limit)
      .lean();

    const total = await GeneratedPost.countDocuments({ userId });

    return NextResponse.json({ posts, total, page, limit });
  } catch (err) {
    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    return NextResponse.json({ error: 'Failed to fetch history' }, { status: 500 });
  }
}

import { NextRequest } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { requireAuth } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { scrapeWebsite } from '@/lib/firecrawl';
import { triggerN8nWorkflow } from '@/lib/n8n';
import { generateRequestSchema } from '@/lib/validations';
import { optimizePromptForPlatform, type PlatformId } from '@/lib/platforms';
import { checkRateLimit } from '@/lib/rate-limit';
import { sanitizeUrl } from '@/lib/sanitize';
import { GeneratedPost } from '@/models/GeneratedPost';
import { deductCredit, trackUsage, ensureUser } from '@/lib/user-service';
import { getAuthUser } from '@/lib/auth';

export const maxDuration = 120;

function sse(data: Record<string, unknown>): string {
  return `data: ${JSON.stringify(data)}\n\n`;
}

export async function POST(req: NextRequest) {
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    async start(controller) {
      const send = (payload: Record<string, unknown>) => {
        controller.enqueue(encoder.encode(sse(payload)));
      };

      try {
        const userId = await requireAuth();
        const authUser = await getAuthUser();
        const body = await req.json();
        const parsed = generateRequestSchema.safeParse(body);

        if (!parsed.success) {
          send({ type: 'error', message: 'Validation failed' });
          controller.close();
          return;
        }

        const rate = await checkRateLimit(`generate:${userId}`);
        if (!rate.allowed) {
          send({ type: 'error', message: 'Rate limit exceeded' });
          controller.close();
          return;
        }

        await connectDB();
        await ensureUser({
          clerkId: userId,
          email: authUser?.email ?? '',
          name: authUser?.name ?? 'User',
        });

        const hasCredit = await deductCredit(userId, 1);
        if (!hasCredit) {
          send({ type: 'error', message: 'Insufficient credits' });
          controller.close();
          return;
        }

        const executionId = uuidv4();
        const { websiteUrl, userPrompt, platform } = parsed.data;
        const safeUrl = sanitizeUrl(websiteUrl);
        const optimizedPrompt = optimizePromptForPlatform(
          userPrompt,
          platform as PlatformId
        );

        send({ type: 'status', message: 'Crawling website...', executionId });

        const scraped = await scrapeWebsite(safeUrl);
        send({
          type: 'preview',
          title: scraped.title,
          description: scraped.description,
          excerpt: scraped.markdown.slice(0, 500),
        });

        send({ type: 'status', message: 'Generating AI content...' });

        const result = await triggerN8nWorkflow({
          websiteUrl: safeUrl,
          scrapedContent: scraped.markdown,
          userPrompt,
          optimizedPrompt,
          platform: platform as PlatformId,
          userId,
          executionId,
        });

        await GeneratedPost.create({
          userId,
          executionId,
          websiteUrl: safeUrl,
          userPrompt,
          platform,
          status: 'completed',
          content: result.content ?? '',
          summary: result.summary,
          qualityScore: result.qualityScore,
          wordCount: result.wordCount,
        });

        await trackUsage(userId, platform, 1);

        send({
          type: 'complete',
          executionId,
          content: result.content,
          summary: result.summary,
          qualityScore: result.qualityScore,
          wordCount: result.wordCount,
          platform: result.platformName,
        });
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Stream failed';
        send({ type: 'error', message });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  });
}

import { NextResponse } from 'next/server';
import { requireAuth } from '@/lib/auth';
import { connectDB } from '@/lib/db';
import { User, type IUser } from '@/models/User';
import { UsageAnalytics } from '@/models/UsageAnalytics';
import { GeneratedPost } from '@/models/GeneratedPost';
import { WorkflowExecution } from '@/models/WorkflowExecution';

export async function GET() {
  try {
    const userId = await requireAuth();
    await connectDB();

    const user = await User.findOne({ clerkId: userId }).lean<IUser>();
    const analytics = await UsageAnalytics.find({ userId })
      .sort({ date: -1 })
      .limit(30)
      .lean();

    const totalPosts = await GeneratedPost.countDocuments({ userId });
    const completedExecutions = await WorkflowExecution.countDocuments({
      userId,
      status: 'completed',
    });
    const failedExecutions = await WorkflowExecution.countDocuments({
      userId,
      status: 'failed',
    });

    const platformBreakdown = await GeneratedPost.aggregate([
      { $match: { userId } },
      { $group: { _id: '$platform', count: { $sum: 1 } } },
      { $sort: { count: -1 } },
    ]);

    return NextResponse.json({
      user: {
        credits: user?.credits ?? 0,
        plan: user?.plan ?? 'free',
        name: user?.name,
      },
      stats: {
        totalPosts,
        completedExecutions,
        failedExecutions,
      },
      analytics,
      platformBreakdown: platformBreakdown.map((p) => ({
        platform: p._id,
        count: p.count,
      })),
    });
  } catch (err) {
    if (err instanceof Error && err.message === 'UNAUTHORIZED') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }
    return NextResponse.json({ error: 'Failed to fetch usage' }, { status: 500 });
  }
}

export const dynamic = 'force-dynamic';

import { DashboardView } from '@/components/DashboardView';

export default function DashboardPage() {
  return <DashboardView />;
}

:root {
  --bg: #0a0a0f;
  --bg-elevated: #12121a;
  --bg-card: #16161f;
  --border: #2a2a3a;
  --text: #f4f4f8;
  --text-muted: #9898b0;
  --accent: #6366f1;
  --accent-hover: #818cf8;
  --success: #22c55e;
  --error: #ef4444;
  --gradient: linear-gradient(135deg, #6366f1 0%, #a855f7 50%, #ec4899 100%);
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  --radius: 12px;
  --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
}

[data-theme='light'] {
  --bg: #f8f9fc;
  --bg-elevated: #ffffff;
  --bg-card: #ffffff;
  --border: #e2e4ec;
  --text: #0f0f14;
  --text-muted: #5c5c70;
  --shadow: 0 8px 32px rgba(15, 15, 20, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  min-height: 100vh;
}

a {
  color: var(--accent);
  text-decoration: none;
}

a:hover {
  color: var(--accent-hover);
}

.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 1.25rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 1.25rem;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.9rem;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--gradient);
  color: white;
}

.btn-primary:hover:not(:disabled) {
  opacity: 0.9;
  transform: translateY(-1px);
}

.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}

.btn-ghost:hover {
  background: var(--bg-elevated);
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.input,
.textarea,
.select {
  width: 100%;
  padding: 0.75rem 1rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color 0.2s;
}

.input:focus,
.textarea:focus,
.select:focus {
  outline: none;
  border-color: var(--accent);
}

.textarea {
  min-height: 120px;
  resize: vertical;
}

.label {
  display: block;
  font-size: 0.85rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
  color: var(--text-muted);
}

.field {
  margin-bottom: 1.25rem;
}

.spinner {
  width: 20px;
  height: 20px;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.skeleton {
  background: linear-gradient(
    90deg,
    var(--bg-elevated) 25%,
    var(--border) 50%,
    var(--bg-elevated) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
  border-radius: 6px;
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@media (max-width: 768px) {
  .hide-mobile {
    display: none !important;
  }
}

import type { Metadata } from 'next';
import { ClerkProvider } from '@clerk/nextjs';
import { Toaster } from 'sonner';
import { ThemeProvider } from '@/components/ThemeProvider';
import { Header } from '@/components/Header';
import './globals.css';

export const metadata: Metadata = {
  title: 'SocialFlow AI — Social Media Content from Any URL',
  description:
    'AI-powered SaaS that turns website content into platform-optimized social posts using Firecrawl and n8n.',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <ClerkProvider>
      <html lang="en" data-theme="dark">
        <body>
          <ThemeProvider>
            <Header />
            <main>{children}</main>
            <Toaster richColors position="top-right" theme="system" />
          </ThemeProvider>
        </body>
      </html>
    </ClerkProvider>
  );
}

export const dynamic = 'force-dynamic';

import { Hero } from '@/components/Hero';
import { ProductFeatures } from '@/components/ProductFeatures';
import { GenerateForm } from '@/components/GenerateForm';

export default function HomePage() {
  return (
    <>
      <Hero />
      <GenerateForm />
      <ProductFeatures />
      <footer
        style={{
          borderTop: '1px solid var(--border)',
          padding: '2rem 0',
          textAlign: 'center',
          color: 'var(--text-muted)',
          fontSize: '0.85rem',
        }}
      >
        <div className="container">
          SocialFlow AI — Powered by Firecrawl, n8n, and Next.js
        </div>
      </footer>
    </>
  );
}

